<template>
  <div class="leadership-dashboard">
    <header class="lead-header"><div><h1>Procurement Dashboard</h1><p>Portfolio overview of all procurement projects, status, risk, milestones, and financial activity.</p></div><div class="header-actions"><label><Search :size="17"/><input v-model="filters.search" placeholder="Search Projects…"/></label><RouterLink class="primary-action" to="/projects/new"><Plus :size="17"/> New Project</RouterLink></div></header>
    <section class="portfolio-filters"><label>Date Range<select v-model="filters.dateRange"><option>All Time</option><option>This Month</option><option>This Quarter</option><option>This Fiscal Year</option></select></label><label>Procurement Owner<select v-model="filters.owner"><option value="">All</option><option v-for="u in owners" :key="u.id" :value="u.id">{{ u.name }}</option></select></label><label>Customer<select v-model="filters.customer"><option value="">All</option><option v-for="c in customers" :key="c">{{ c }}</option></select></label><label>Status<select v-model="filters.status"><option value="">All</option><option v-for="s in statuses" :key="s">{{ s }}</option></select></label><label>Priority<select v-model="filters.priority"><option value="">All</option><option>Critical</option><option>High</option><option>Medium</option><option>Low</option></select></label><label>Project Type<select v-model="filters.type"><option value="">All</option><option v-for="t in projectTypes" :key="t">{{ t }}</option></select></label></section>
    <section class="kpis"><button v-for="k in kpiCards" :key="k.label" :class="k.tone" @click="riskFilter=k.filter"><span>{{ k.label }}</span><strong>{{ k.money?currency(k.value):k.value.toLocaleString() }}</strong><small>{{ k.detail }}</small></button></section>
    <nav class="view-tabs"><button v-for="v in views" :key="v" :class="{active:view===v}" @click="setView(v)">{{ v }} View</button></nav>
    <section class="workspace"><main>
      <div class="board-controls"><label>Group By<select v-model="groupBy"><option>Status</option><option>Procurement Owner</option><option>Customer</option><option>Priority</option></select></label><label>Sort By<select v-model="sortBy"><option>Priority</option><option>Due Date</option><option>Project Value</option><option>Project Number</option><option>Recently Updated</option></select></label><button @click="compact=!compact">{{ compact?'Detailed':'Compact' }} Cards</button></div>
      <section v-if="!portfolio.length" class="empty">No projects match the selected portfolio filters.</section>
      <section v-else-if="view==='Board'" class="kanban"><article v-for="group in groupedPortfolio" :key="group.name" class="kanban-column"><header><div><strong>{{ group.name }}</strong><span>{{ group.rows.length }} projects</span></div><b>{{ currency(sum(group.rows,'projectValue')) }}</b></header><div class="cards"><RouterLink v-for="row in group.rows" :key="row.project.id" :to="`/projects/${row.project.id}`" class="project-card" :class="{risk:row.riskLevel!=='On Track'}"><div class="card-title"><span>{{ row.project.projectNumber }}</span><RiskBadge :value="row.riskLevel"/></div><h3>{{ row.project.projectName }}</h3><p>{{ row.project.customer }}</p><dl v-if="!compact"><div><dt>Owner</dt><dd>{{ row.owner }}</dd></div><div><dt>Priority</dt><dd>{{ row.priority }}</dd></div></dl><div class="progress"><span :style="{width:`${row.progress}%`}"/></div><div class="card-bottom"><b>{{ row.progress }}%</b><strong>{{ currency(row.projectValue) }}</strong></div><small>{{ row.nextAction }}</small><small v-if="row.dueDate">Due {{ date(row.dueDate) }} · {{ dueLabel(row.daysUntilDue) }}</small><small v-else>Not Scheduled</small></RouterLink></div></article></section>
      <section v-else-if="view==='Timeline'" class="timeline"><header><strong>Portfolio Timeline</strong><select v-model="zoom"><option>Day</option><option>Week</option><option>Month</option><option>Quarter</option></select></header><div v-for="row in portfolio" :key="row.project.id" class="timeline-row"><RouterLink :to="`/projects/${row.project.id}`">{{ row.project.projectNumber }} · {{ row.project.projectName }}</RouterLink><div class="track"><span v-if="row.hasSchedule" :style="timelineStyle(row)" :class="{late:row.daysUntilDue<0}"/><em v-else>Not Scheduled</em></div></div></section>
      <section v-else-if="view==='Gantt'" class="gantt table-scroll"><table><thead><tr><th>Project #</th><th>Project</th><th>Customer</th><th>Owner</th><th>Status</th><th>Priority</th><th>%</th><th>Schedule</th></tr></thead><tbody><tr v-for="row in portfolio" :key="row.project.id"><td><RouterLink :to="`/projects/${row.project.id}`">{{ row.project.projectNumber }}</RouterLink></td><td>{{ row.project.projectName }}</td><td>{{ row.project.customer }}</td><td>{{ row.owner }}</td><td>{{ row.stage }}</td><td>{{ row.priority }}</td><td>{{ row.progress }}%</td><td><div class="gantt-track"><span v-if="row.hasSchedule" :style="timelineStyle(row)"/><em v-else>Not Scheduled</em></div></td></tr></tbody></table></section>
      <section v-else class="portfolio-table table-scroll"><table><thead><tr><th>Project #</th><th>Project Name</th><th>Customer</th><th>Owner</th><th>Status</th><th>Priority</th><th class="money">Project Value</th><th class="money">Quoted</th><th class="money">PO Value</th><th class="money">Open PO</th><th>%</th><th>Next Action</th><th>Required Date</th><th>Risk</th><th>Last Updated</th></tr></thead><tbody><tr v-for="row in portfolio" :key="row.project.id"><td><RouterLink :to="`/projects/${row.project.id}`">{{ row.project.projectNumber }}</RouterLink></td><td><RouterLink :to="`/projects/${row.project.id}`">{{ row.project.projectName }}</RouterLink></td><td>{{ row.project.customer }}</td><td>{{ row.owner }}</td><td>{{ row.stage }}</td><td>{{ row.priority }}</td><td class="money">{{ currency(row.projectValue) }}</td><td class="money">{{ currency(row.quotedValue) }}</td><td class="money">{{ currency(row.poValue) }}</td><td class="money">{{ currency(row.openPoValue) }}</td><td>{{ row.progress }}%</td><td>{{ row.nextAction }}</td><td>{{ row.dueDate?date(row.dueDate):'Not Scheduled' }}</td><td><RiskBadge :value="row.riskLevel"/></td><td>{{ row.project.updatedAt?date(row.project.updatedAt):'—' }}</td></tr></tbody></table></section>
    </main><aside><section class="summary-card"><h2>Portfolio Status</h2><div class="donut" :style="donutStyle"><div><strong>{{ portfolio.length }}</strong><span>Projects</span></div></div><ul><li v-for="s in statusSummary" :key="s.label"><i :class="s.class"/>{{ s.label }}<b>{{ s.value }}</b></li></ul></section><section class="summary-card"><h2>Procurement Health</h2><div v-for="h in health" :key="h.label" class="health"><span>{{ h.label }}<b>{{ h.value }}%</b></span><div><i :style="{width:`${h.value}%`}"/></div></div></section><section class="summary-card"><h2>Value by Customer</h2><div v-for="c in customerValues" :key="c.name" class="customer-value"><span>{{ c.name }}</span><b>{{ currency(c.value) }}</b></div><div class="customer-total"><span>Total</span><b>{{ currency(sum(portfolio,'projectValue')) }}</b></div></section></aside></section>
    <section class="insight-grid"><Panel title="Upcoming Milestones"><table><thead><tr><th>Project</th><th>Milestone</th><th>Owner</th><th>Due</th><th>Status</th></tr></thead><tbody><tr v-for="m in milestones" :key="m.key"><td><RouterLink :to="`/projects/${m.projectId}`">{{ m.projectNumber }}</RouterLink></td><td>{{ m.title }}</td><td>{{ m.owner }}</td><td>{{ date(m.dueDate) }}</td><td><RiskBadge :value="milestoneStatus(m.days)"/></td></tr></tbody></table></Panel><Panel title="Top Risks & Issues"><table><thead><tr><th>Project</th><th>Risk / Issue</th><th>Impact</th><th>Owner</th></tr></thead><tbody><tr v-for="r in topRisks" :key="r.key"><td><RouterLink :to="`/projects/${r.projectId}`">{{ r.projectNumber }}</RouterLink></td><td>{{ r.issue }}</td><td><RiskBadge :value="r.impact"/></td><td>{{ r.owner }}</td></tr></tbody></table></Panel></section>
    <section class="summary-card workload"><h2>Procurement Team Workload</h2><div class="workload-grid"><button v-for="w in workload" :key="w.id" @click="filters.owner=w.id"><strong>{{ w.name }}</strong><span>{{ w.projects }} Projects · {{ w.atRisk }} At Risk · {{ currency(w.openPo) }} Open</span><small>{{ w.vendorActions }} vendor actions · {{ w.upcoming }} upcoming dates</small></button></div></section>
    <Panel title="Needs Leadership Attention" prominent><table><thead><tr><th>Project</th><th>Problem</th><th>Owner</th><th>Age</th><th>Financial Impact</th><th>Recommended Next Action</th></tr></thead><tbody><tr v-for="a in attention" :key="a.project.id"><td><RouterLink :to="`/projects/${a.project.id}`">{{ a.project.projectNumber }}</RouterLink></td><td>{{ a.riskReason }}</td><td>{{ a.owner }}</td><td>{{ Math.max(0,-a.daysUntilDue) }} days</td><td>{{ currency(a.openPoValue||a.projectValue) }}</td><td>{{ a.nextAction }}</td></tr></tbody></table></Panel>
  </div>
</template>

<script setup lang="ts">
import { computed, defineComponent, h, onMounted, onUnmounted, reactive, ref } from 'vue'
import { Plus, Search } from '@lucide/vue'
import { calculateQuoteSummary, currency } from '../../services/calculations'
import { loadUsers } from '../../services/auth'
import { loadProjects } from '../../services/localProjects'
import type { Project, UserProfile } from '../../types'
type View='Board'|'Timeline'|'Gantt'|'Table'; type Row=ReturnType<typeof portfolioRow>
const projects=ref<Project[]>(loadProjects()),users=ref<UserProfile[]>(loadUsers()),view=ref<View>((localStorage.getItem('atlas.leadershipView') as View)||'Board'),zoom=ref('Month'),groupBy=ref('Status'),sortBy=ref('Priority'),compact=ref(false),riskFilter=ref('')
const filters=reactive({search:'',dateRange:'All Time',owner:'',customer:'',status:'',priority:'',type:''})
const owners=computed(()=>users.value.filter(u=>u.active)),customers=computed(()=>[...new Set(projects.value.map(p=>p.customer).filter(Boolean))].sort()),statuses=computed(()=>[...new Set(projects.value.map(p=>stage(p)))]),projectTypes=computed(()=>[...new Set(projects.value.map(p=>p.projectType))])
const allRows=computed(()=>projects.value.map(p=>portfolioRow(p,users.value))),portfolio=computed(()=>allRows.value.filter(r=>matches(r)).sort(sortRows))
const kpiCards=computed(()=>[{label:'Total Projects',value:portfolio.value.length,detail:'Filtered portfolio',tone:'',filter:'',money:false},{label:'On Track',value:portfolio.value.filter(r=>r.riskLevel==='On Track').length,detail:'No active exception',tone:'good',filter:'On Track',money:false},{label:'At Risk',value:portfolio.value.filter(r=>r.riskLevel==='At Risk').length,detail:'Warning indicators',tone:'warn',filter:'At Risk',money:false},{label:'Overdue / Needs Attention',value:portfolio.value.filter(r=>r.riskLevel==='Overdue').length,detail:'Leadership intervention',tone:'bad',filter:'Overdue',money:false},{label:'Total Committed Value',value:sum(portfolio.value,'poValue'),detail:'Issued purchase orders at cost',tone:'blue',filter:'',money:true},{label:'Open PO Value',value:sum(portfolio.value,'openPoValue'),detail:'PO cost not fully received',tone:'blue',filter:'',money:true}])
const views:View[]=['Board','Timeline','Gantt','Table']
const groupedPortfolio=computed(()=>{const map=new Map<string,Row[]>();for(const r of portfolio.value){const key=groupBy.value==='Status'?r.stage:groupBy.value==='Procurement Owner'?r.owner:groupBy.value==='Customer'?r.project.customer:r.priority;if(!map.has(key))map.set(key,[]);map.get(key)!.push(r)}return[...map].map(([name,rows])=>({name,rows}))})
const statusSummary=computed(()=>['On Track','At Risk','Overdue','Completed','Planning'].map((label,i)=>({label,value:portfolio.value.filter(r=>label==='Planning'?r.stage==='Planning':label==='Completed'?r.stage==='Completed':r.riskLevel===label).length,class:`s${i}`})))
const donutStyle=computed(()=>{const total=Math.max(1,portfolio.value.length),a=statusSummary.value.map(s=>s.value/total*100),p=[a[0],a[0]+a[1],a[0]+a[1]+a[2],a[0]+a[1]+a[2]+a[3]];return{background:`conic-gradient(#22c55e 0 ${p[0]}%,#f59e0b ${p[0]}% ${p[1]}%,#ef4444 ${p[1]}% ${p[2]}%,#3b82f6 ${p[2]}% ${p[3]}%,#94a3b8 ${p[3]}% 100%)`}})
const health=computed(()=>{const active=portfolio.value.filter(r=>r.stage!=='Completed'),safe=(fn:(r:Row)=>boolean)=>active.length?Math.round(active.filter(fn).length/active.length*100):100;return[{label:'Overall Portfolio Health',value:safe(r=>r.riskLevel==='On Track')},{label:'Schedule Health',value:safe(r=>!r.dueDate||r.daysUntilDue>=0)},{label:'Procurement Health',value:safe(r=>!['Pending Approval','Ready for PO'].includes(r.stage)||r.daysUntilDue>=0)},{label:'Vendor Health',value:safe(r=>!r.vendorRisk)}]})
const customerValues=computed(()=>{const map=new Map<string,number>();for(const r of portfolio.value)map.set(r.project.customer||'Unassigned',(map.get(r.project.customer||'Unassigned')||0)+r.projectValue);return[...map].map(([name,value])=>({name,value})).sort((a,b)=>b.value-a.value).slice(0,6)})
const milestones=computed(()=>portfolio.value.filter(r=>r.dueDate).sort((a,b)=>a.daysUntilDue-b.daysUntilDue).slice(0,10).map(r=>({key:r.project.id,projectId:r.project.id,projectNumber:r.project.projectNumber,title:r.nextAction,owner:r.owner,dueDate:r.dueDate,days:r.daysUntilDue})))
const topRisks=computed(()=>portfolio.value.filter(r=>r.riskLevel!=='On Track').sort((a,b)=>priorityRank(b.priority)-priorityRank(a.priority)||a.daysUntilDue-b.daysUntilDue).slice(0,10).map(r=>({key:r.project.id,projectId:r.project.id,projectNumber:r.project.projectNumber,issue:r.riskReason,impact:r.riskLevel==='Overdue'?'Critical':'High',owner:r.owner})))
const workload=computed(()=>owners.value.map(u=>{const rows=allRows.value.filter(r=>r.project.assignedUserIds?.includes(u.id));return{id:u.id,name:u.name,projects:rows.length,atRisk:rows.filter(r=>r.riskLevel!=='On Track').length,openPo:sum(rows,'openPoValue'),vendorActions:rows.filter(r=>r.vendorRisk).length,upcoming:rows.filter(r=>r.daysUntilDue>=0&&r.daysUntilDue<=14).length}}).filter(w=>w.projects).sort((a,b)=>b.projects-a.projects))
const attention=computed(()=>portfolio.value.filter(r=>r.riskLevel==='Overdue'||(r.priority==='Critical'&&r.riskLevel!=='On Track')).slice(0,12))
onMounted(()=>{window.addEventListener('cronos:projects-changed',refresh);window.addEventListener('cronos:users-changed',refresh)})
onUnmounted(()=>{window.removeEventListener('cronos:projects-changed',refresh);window.removeEventListener('cronos:users-changed',refresh)})
function refresh(){projects.value=loadProjects();users.value=loadUsers()} function setView(v:View){view.value=v;localStorage.setItem('atlas.leadershipView',v)}
function portfolioRow(project:Project,userList:UserProfile[]){const quote=project.quotes.reduce((s,q)=>{const x=calculateQuoteSummary(q.lines,q.contractFeeEnabled,q.shippingCost);return{cost:s.cost+x.totalCost,sell:s.sell+x.customerTotal}},{cost:0,sell:0});const poValue=project.purchaseOrders.reduce((s,p)=>s+p.totalCost,0),openPoValue=project.purchaseOrders.filter(p=>!['Received','Delivered','Cancelled'].includes(p.status)).reduce((s,p)=>s+p.totalCost,0),received=project.purchaseOrders.flatMap(p=>p.lines).reduce((s,l)=>s+l.quantityReceived,0),ordered=project.purchaseOrders.flatMap(p=>p.lines).reduce((s,l)=>s+l.quantityOrdered,0);const progress=project.status==='Cancelled'?100:ordered?Math.min(100,Math.round(received/ordered*100)):project.quotes.length?project.purchaseOrders.length?45:25:10;const dueDate=earliest([project.endDate,...project.purchaseOrders.flatMap(p=>[p.expectedDeliveryDate||'',p.estimatedShipDate||''])]);const daysUntilDue=dueDate?Math.ceil((Date.parse(dueDate)-Date.now())/86400000):9999;const vendorRisk=project.purchaseOrders.some(p=>!p.trackingNumber&&p.estimatedShipDate&&Date.parse(p.estimatedShipDate)<Date.now());const st=stage(project),priority=daysUntilDue<0?'Critical':daysUntilDue<=14||vendorRisk?'High':daysUntilDue<=30?'Medium':'Low';const riskLevel=daysUntilDue<0?'Overdue':vendorRisk||priority==='High'?'At Risk':'On Track';const ownerNames=userList.filter(u=>project.assignedUserIds?.includes(u.id)).map(u=>u.name);const nextAction=vendorRisk?'Obtain vendor acknowledgement / tracking':st==='Pending Approval'?'Secure customer approval':st==='Ready for PO'?'Issue purchase order':st==='Delivery / Receiving'?'Confirm shipment and receiving':'Review next procurement milestone';return{project,owner:ownerNames.join(', ')||project.projectManager||'Unassigned',stage:st,priority,progress,projectValue:quote.sell||poValue||project.materialBudget||project.checkbookStartingBalance||0,quotedValue:quote.sell,poValue,openPoValue,dueDate,daysUntilDue,hasSchedule:Boolean(project.startDate&&dueDate),vendorRisk,riskLevel,riskReason:riskLevel==='Overdue'?'Required or delivery date is overdue':vendorRisk?'Expected ship date missed or tracking missing':priority==='High'?'Required date is approaching':'No active exception',nextAction}}
function stage(p:Project){if(['Delivered','Cancelled'].includes(p.status))return'Completed';if(['Received','Partially Received','Shipped','In Transit to Cronos'].includes(p.status))return'Delivery / Receiving';if(p.purchaseOrders.length)return'PO Issued / Active';if(p.status==='Customer Approved')return'Ready for PO';if(p.quotes.some(q=>q.status==='Quoted'))return'Pending Approval';if(p.quotes.length)return'In Progress / Pricing';return'Planning'}
function matches(r:Row){const q=filters.search.toLowerCase(),text=[r.project.projectNumber,r.project.projectName,r.project.customer,r.owner].join(' ').toLowerCase();return(!q||text.includes(q))&&(!filters.owner||r.project.assignedUserIds?.includes(filters.owner))&&(!filters.customer||r.project.customer===filters.customer)&&(!filters.status||r.stage===filters.status)&&(!filters.priority||r.priority===filters.priority)&&(!filters.type||r.project.projectType===filters.type)&&(!riskFilter.value||r.riskLevel===riskFilter.value)}
function sortRows(a:Row,b:Row){if(sortBy.value==='Priority')return priorityRank(b.priority)-priorityRank(a.priority);if(sortBy.value==='Due Date')return a.daysUntilDue-b.daysUntilDue;if(sortBy.value==='Project Value')return b.projectValue-a.projectValue;if(sortBy.value==='Recently Updated')return Date.parse(b.project.updatedAt||'')-Date.parse(a.project.updatedAt||'');return a.project.projectNumber.localeCompare(b.project.projectNumber,undefined,{numeric:true})}
function priorityRank(v:string){return({Low:1,Medium:2,High:3,Critical:4} as Record<string,number>)[v]||0} function earliest(values:string[]){return values.filter(Boolean).sort()[0]||''} function sum(rows:any[],key:string){return rows.reduce((s,r)=>s+Number(r[key]||0),0)} function date(v:string){return new Intl.DateTimeFormat(undefined,{dateStyle:'medium'}).format(new Date(v))} function dueLabel(d:number){return d<0?`${Math.abs(d)} days overdue`:d===0?'Due today':`${d} days remaining`} function milestoneStatus(d:number){return d<0?'Overdue':d===0?'Due Today':d<=7?'Due Soon':'On Track'} function timelineStyle(row:Row){const start=Date.parse(row.project.startDate),end=Date.parse(row.dueDate),yearStart=new Date(new Date().getFullYear(),0,1).getTime(),yearEnd=new Date(new Date().getFullYear(),11,31).getTime();return{left:`${Math.max(0,(start-yearStart)/(yearEnd-yearStart)*100)}%`,width:`${Math.max(2,(end-start)/(yearEnd-yearStart)*100)}%`}}
const RiskBadge=defineComponent({props:{value:{type:String,required:true}},setup:p=>()=>h('span',{class:`risk-badge risk-${p.value.toLowerCase().replaceAll(' ','-')}`},p.value)})
const Panel=defineComponent({props:{title:String,prominent:Boolean},setup:(p,{slots})=>()=>h('section',{class:['insight-panel',p.prominent?'prominent':'']},[h('h2',p.title),slots.default?.()])})
</script>

<style scoped>
.leadership-dashboard{display:grid;gap:1rem;width:min(100%,1800px);margin:auto;color:#0f172a}.lead-header,.header-actions,.board-controls,.timeline header{display:flex;align-items:center;justify-content:space-between;gap:1rem}.lead-header h1{margin:0}.lead-header p{margin:.25rem 0;color:#64748b}.header-actions label{display:flex;align-items:center;gap:.4rem;border:1px solid #cbd5e1;background:#fff;border-radius:8px;padding:.5rem .7rem}.header-actions input{border:0;outline:0;width:210px}.portfolio-filters{display:grid;grid-template-columns:repeat(6,1fr);gap:.6rem;background:#fff;border:1px solid #dbe3ec;border-radius:10px;padding:.75rem}.portfolio-filters label,.board-controls label{display:grid;gap:.25rem;font-size:.66rem;font-weight:700;text-transform:uppercase;color:#64748b}.portfolio-filters select,.board-controls select,.board-controls button,.timeline select{border:1px solid #cbd5e1;border-radius:6px;background:#fff;padding:.45rem}.kpis{display:grid;grid-template-columns:repeat(6,1fr);gap:.65rem}.kpis button{background:#fff;border:1px solid #dbe3ec;border-top:3px solid #94a3b8;border-radius:9px;padding:.8rem;text-align:left}.kpis span,.kpis small,.project-card small{display:block;color:#64748b}.kpis span{font-size:.65rem;font-weight:800;text-transform:uppercase}.kpis strong{display:block;font-size:1.4rem;margin:.2rem 0}.kpis .good{border-top-color:#22c55e}.kpis .warn{border-top-color:#f59e0b}.kpis .bad{border-top-color:#ef4444}.kpis .blue{border-top-color:#3b82f6}.view-tabs{display:flex;border-bottom:1px solid #cbd5e1}.view-tabs button{border:0;background:none;padding:.7rem 1rem;color:#64748b;font-weight:700;border-bottom:3px solid transparent}.view-tabs .active{color:#2563eb;border-color:#2563eb}.workspace{display:grid;grid-template-columns:minmax(0,1fr) 270px;gap:1rem}.workspace main{min-width:0}.board-controls{justify-content:flex-end;margin-bottom:.7rem}.board-controls label{min-width:150px}.kanban{display:flex;gap:.7rem;overflow:auto;padding-bottom:.5rem}.kanban-column{background:#f1f5f9;border:1px solid #dbe3ec;border-radius:9px;min-width:255px;width:255px}.kanban-column>header{display:flex;justify-content:space-between;padding:.7rem;border-bottom:1px solid #dbe3ec}.kanban-column header span{display:block;font-size:.68rem;color:#64748b}.cards{display:grid;gap:.55rem;padding:.55rem;max-height:650px;overflow:auto}.project-card{display:block;background:#fff;border:1px solid #dbe3ec;border-left:3px solid #3b82f6;border-radius:8px;padding:.7rem;text-decoration:none;color:inherit}.project-card.risk{border-left-color:#f59e0b}.project-card h3{font-size:.82rem;margin:.3rem 0}.project-card p{font-size:.72rem;color:#64748b;margin:.2rem 0}.card-title,.card-bottom,.project-card dl{display:flex;justify-content:space-between;gap:.5rem}.project-card dl{font-size:.68rem}.project-card dt{color:#64748b}.project-card dd{margin:0}.progress{height:5px;background:#e2e8f0;border-radius:9px;margin:.55rem 0}.progress span{display:block;height:100%;background:#3b82f6;border-radius:9px}.risk-badge{display:inline-flex;border-radius:99px;padding:.16rem .4rem;font-size:.62rem;font-weight:800;background:#e2e8f0;color:#475569}.risk-at-risk,.risk-due-soon{background:#fef3c7;color:#92400e}.risk-overdue,.risk-critical{background:#fee2e2;color:#991b1b}.risk-on-track{background:#dcfce7;color:#166534}.timeline,.summary-card,.insight-panel{background:#fff;border:1px solid #dbe3ec;border-radius:9px;padding:.8rem}.timeline-row{display:grid;grid-template-columns:260px 1fr;align-items:center;border-top:1px solid #edf2f7;padding:.6rem 0;font-size:.73rem}.track,.gantt-track{height:22px;background:repeating-linear-gradient(90deg,#f8fafc 0,#f8fafc 9.8%,#e2e8f0 10%);position:relative}.track span,.gantt-track span{position:absolute;height:10px;top:6px;background:#3b82f6;border-radius:9px}.track span.late{background:#ef4444}.track em{padding-left:.5rem;color:#94a3b8}.table-scroll{overflow:auto;background:#fff;border:1px solid #dbe3ec;border-radius:9px}table{width:1